head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > maxlength]<br/>SearchBox 컴포넌트에 입력 가능한 최대 길이를 설정합니다.",
    "validation" : [
        "maxByteLength 와 maxlength 를 모두 설정하면 설정값이 작은 속성이 적용됩니다.",
        "maxByteLength 와 maxlength 를 같은 값으로 설정하면 maxByteLength 가 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}



// target1 : maxByteLength=4, maxlength=5 (작은 maxByteLength 적용)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라마바");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

// target2 : maxByteLength=4, maxlength=4 (같은 값 → maxByteLength 적용)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나다라마바");
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}

// target3 : maxByteLength=10, maxlength=3 (작은 maxlength 적용)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("abcdefg");
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3);
};


scwin.btn_setAll_onclick = function (e) {
    for (var i = 1; i <= 3; i ++)
        eval("scwin.btn_setValue"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i <= 3; i ++)
        eval("scwin.btn_getText"+i+"_onclick()");
};
